effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 20)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.VIT, 3)\n    effect:addMod(xi.mod.FOOD_ACCP, 10)\n    effect:addMod(xi.mod.FOOD_ACC_CAP, 80)\n    effect:addMod(xi.mod.FOOD_RACCP, 10)\n    effect:addMod(xi.mod.FOOD_RACC_CAP, 80)\n    effect:addMod(xi.mod.MACC, 50)\n    target:addPetMod(xi.mod.FOOD_HP, 20)\n    target:addPetMod(xi.mod.DEX, 2)\n    target:addPetMod(xi.mod.VIT, 3)\n    target:addPetMod(xi.mod.FOOD_ACCP, 10)\n    target:addPetMod(xi.mod.FOOD_ACC_CAP, 105)\n    target:addPetMod(xi.mod.FOOD_RACCP, 10)\n    target:addPetMod(xi.mod.FOOD_RACC_CAP, 105)\n    target:addPetMod(xi.mod.MACC, 75)\nend\n\nitemObject.onEffectLose = function(target, effect)\n    target:delPetMod(xi.mod.FOOD_HP, 20)\n    target:delPetMod(xi.mod.DEX, 2)\n    target:delPetMod(xi.mod.VIT, 3)\n    target:delPetMod(xi.mod.FOOD_ACCP, 10)\n    target:delPetMod(xi.mod.FOOD_ACC_CAP, 105)\n    target:delPetMod(xi.mod.FOOD_RACCP, 10)\n    target:delPetMod(xi.mod.FOOD_RACC_CAP, 105)\n    target:delPetMod(xi.mod.MACC, 75)\nend\n\nreturn itemObject\n"},["scripts/items/rolanberry_daifuku_+1.lua"]={["Path"]="scripts/items/rolanberry_daifuku_+1.lua",["SHA256"]="b9703ffed2290176bc9f1a7e990e707e2f5ebba30468b3fd8f4ac9728bd3c49e",["Text"]="-----------------------------------\n-- ID: 6340\n-- Item: rolanberry_daifuku_+1\n-- Food Effect: 60 Min, All Races\n-----------------------------------\n-- HP +30\n-- DEX +3\n-- VIT +4\n-- Accuracy +11% (cap 85)\n-- Ranged Accuracy +11% (cap 85)\n-- Magic Accuracy +55\n-- Pet:\n-- HP +30\n-- DEX +3\n-- VIT +4\n-- Accuracy +11% (cap 110)\n-- Ranged Accuracy +11% (cap 110)\n-- Magic Accuracy +80\n-- https://www.bg-wiki.com/bg/Rolan._Daifuku_%2B1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 30)\n    effect:addMod(xi.mod.DEX, 3)\n    effect:addMod(xi.mod.VIT, 4)\n    effect:addMod(xi.mod.FOOD_ACCP, 11)\n    effect:addMod(xi.mod.FOOD_ACC_CAP, 85)\n    effect:addMod(xi.mod.FOOD_RACCP, 11)\n    effect:addMod(xi.mod.FOOD_RACC_CAP, 85)\n    effect:addMod(xi.mod.MACC, 55)\n    target:addPetMod(xi.mod.FOOD_HP, 30)\n    target:addPetMod(xi.mod.DEX, 3)\n    target:addPetMod(xi.mod.VIT, 4)\n    target:addPetMod(xi.mod.FOOD_ACCP, 11)\n    target:addPetMod(xi.mod.FOOD_ACC_CAP, 110)\n    target:addPetMod(xi.mod.FOOD_RACCP, 11)\n    target:addPetMod(xi.mod.FOOD_RACC_CAP, 110)\n    target:addPetMod(xi.mod.MACC, 80)\nend\n\nitemObject.onEffectLose = function(target, effect)\n    target:delPetMod(xi.mod.FOOD_HP, 30)\n    target:delPetMod(xi.mod.DEX, 3)\n    target:delPetMod(xi.mod.VIT, 4)\n    target:delPetMod(xi.mod.FOOD_ACCP, 11)\n    target:delPetMod(xi.mod.FOOD_ACC_CAP, 110)\n    target:delPetMod(xi.mod.FOOD_RACCP, 11)\n    target:delPetMod(xi.mod.FOOD_RACC_CAP, 110)\n    target:delPetMod(xi.mod.MACC, 80)\nend\n\nreturn itemObject\n"},["scripts/items/rolanberry_pie.lua"]={["Path"]="scripts/items/rolanberry_pie.lua",["SHA256"]="43a310a9d038663b454ed94a17d1108d0e070f1ed1f0b0513a4f0e56c198d32b",["Text"]="-----------------------------------\n-- ID: 4414\n-- Item: rolanberry_pie\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Magic 50\n-- Agility -1\n-- Intelligence 2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MP, 50)\n    effect:addMod(xi.mod.AGI, -1)\n    effect:addMod(xi.mod.INT, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/rolanberry_pie_+1.lua"]={["Path"]="scripts/items/rolanberry_pie_+1.lua",["SHA256"]="1f2d03189019d07b7cdc1d4180fa0cc4922341aaa99967d391c183fd52a54b80",["Text"]="-----------------------------------\n-- ID: 4339\n-- Item: rolanberry_pie_+1\n-- Food Effect: 60Min, All Races\n-----------------------------------\n-- Magic 60\n-- Intelligence 3\n-- MP Regen While Healing 1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MP, 60)\n    effect:addMod(xi.mod.INT, 3)\n    effect:addMod(xi.mod.MPHEAL, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/roll_of_buche_au_chocolat.lua"]={["Path"]="scripts/items/roll_of_buche_au_chocolat.lua",["SHA256"]="abd106290198c8efb025addfeb735bf0cb6f288937e93ca136cad6d014fbcd39",["Text"]="-----------------------------------\n-- ID: 5550\n-- Item: Roll of Buche Au Chocolat\n-- Food Effect: 3 Hrs, All Races\n-----------------------------------\n-- TODO: Group Effect\n-- HP +8\n-- MP +3% Cap 13\n-- Intelligence +2\n-- HP Recovered while healing +1\n-- MP Recovered while healing +4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MPP, 3)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 13)\n    effect:addMod(xi.mod.FOOD_HP, 8)\n    effect:addMod(xi.mod.INT, 2)\n    effect:addMod(xi.mod.HPHEAL, 1)\n    effect:addMod(xi.mod.MPHEAL, 4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/roll_of_sylvan_excursion.lua"]={["Path"]="scripts/items/roll_of_sylvan_excursion.lua",["SHA256"]="ac16ab7889f420e26c773bbde6be0f1dc05a4944ffeffda907866470a27cddeb",["Text"]="-----------------------------------\n-- ID: 5551\n-- Item: Roll of Sylvan Excursion\n-- Food Effect: 4 Hrs, All Races\n-----------------------------------\n-- TODO: Group Effect\n-- HP +10\n-- MP +3% Cap 15\n-- Intelligence +3\n-- HP Recovered while healing +2\n-- MP Recovered while healing +5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 14400, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MPP, 3)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 15)\n    effect:addMod(xi.mod.FOOD_HP, 10)\n    effect:addMod(xi.mod.INT, 3)\n    effect:addMod(xi.mod.HPHEAL, 2)\n    effect:addMod(xi.mod.MP