will obtain one stack of Roppo Shurikens\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.ROPPO_SHURIKEN, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/rotten_quiver.lua"]={["Path"]="scripts/items/rotten_quiver.lua",["SHA256"]="6b9c45fcdeb1c4291b36bcf3f09e3ac1fb1faf14f4f71b0f8b416616f3a5ad9d",["Text"]="-----------------------------------\n-- ID: 4196\n-- Rotten Quiver\n-- When used, you will obtain one partial stack of Old Arrows\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.OLD_ARROW, math.randomInt(10, 20) } })\nend\n\nreturn itemObject\n"},["scripts/items/royal_omelette.lua"]={["Path"]="scripts/items/royal_omelette.lua",["SHA256"]="4699f83cae71b36a8c7ed7ebf2c2a67e9918d196bad4e6be2dfc62aa23a65eda",["Text"]="-----------------------------------\n-- ID: 4564\n-- Item: royal_omelette\n-- Food Effect: 180Min, All Races\n-----------------------------------\n-- Strength 5\n-- Dexterity 2\n-- Intelligence -3\n-- Mind 4\n-- Attack % 20 (cap 65)\n-- Ranged Attack % 20 (cap 65)\n-----------------------------------\n-- IF ELVAAN ONLY\n-- HP 20\n-- MP 20\n-- Strength 6\n-- Dexterity 2\n-- Intelligence -2\n-- Mind 5\n-- Charisma 4\n-- Attack % 22\n-- Attack Cap 80\n-- Ranged ATT % 22\n-- Ranged ATT Cap 80\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    local targetRace = target:getRace()\n\n    if\n        targetRace == xi.race.ELVAAN_M or\n        targetRace == xi.race.ELVAAN_F\n    then\n        effect:addMod(xi.mod.FOOD_HP, 20)\n        effect:addMod(xi.mod.FOOD_MP, 20)\n        effect:addMod(xi.mod.STR, 6)\n        effect:addMod(xi.mod.DEX, 2)\n        effect:addMod(xi.mod.INT, -2)\n        effect:addMod(xi.mod.MND, 5)\n        effect:addMod(xi.mod.CHR, 4)\n        effect:addMod(xi.mod.FOOD_ATTP, 22)\n        effect:addMod(xi.mod.FOOD_ATT_CAP, 80)\n        effect:addMod(xi.mod.FOOD_RATTP, 22)\n        effect:addMod(xi.mod.FOOD_RATT_CAP, 80)\n    else\n        effect:addMod(xi.mod.STR, 5)\n        effect:addMod(xi.mod.DEX, 2)\n        effect:addMod(xi.mod.INT, -3)\n        effect:addMod(xi.mod.MND, 4)\n        effect:addMod(xi.mod.FOOD_ATTP, 20)\n        effect:addMod(xi.mod.FOOD_ATT_CAP, 65)\n        effect:addMod(xi.mod.FOOD_RATTP, 20)\n        effect:addMod(xi.mod.FOOD_RATT_CAP, 65)\n    end\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/rune_fencer_die.lua"]={["Path"]="scripts/items/rune_fencer_die.lua",["SHA256"]="306b3e75f9896704b1d85b7adae6c85069543b651876faf77d839a8b73b98d98",["Text"]="-----------------------------------\n-- ID: 6369\n-- Rune Fencer Die\n-- Teaches the job ability Runeist's Roll\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnAbility(xi.jobAbility.RUNEISTS_ROLL)\nend\n\nitemObject.onItemUse = function(target)\n    target:addLearnedAbility(xi.jobAbility.RUNEISTS_ROLL)\nend\n\nreturn itemObject\n"},["scripts/items/runners_belt.lua"]={["Path"]="scripts/items/runners_belt.lua",["SHA256"]="de6330165ee4e1596f4c3553d5bfe28ed203a4de70238e59dd55db0f90893fd7",["Text"]="-----------------------------------\n-- ID: 15865\n-- Item: runners_belt\n-- Item Effect: DEX +3\n-- Duration: 60 seconds\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getStatusEffectBySource(xi.effect.DEX_BOOST, xi.effectSourceType.EQUIPPED_ITEM, xi.item.RUNNERS_BELT) ~= nil then\n        target:delStatusEffect(xi.effect.DEX_BOOST, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.RUNNERS_BELT)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.RUNNERS_BELT) then\n        target:addStatusEffect(xi.effect.DEX_BOOST, { power = 3, duration = 60, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.RUNNERS_BELT })\n    end\nend\n\nreturn itemObject\n"},["scripts/items/rusty_bolt_case.lua"]={["Path"]="scripts/items/rusty_bolt_case.lua",["SHA256"]="11c1b37582f667adb5ff18764294d14fd76607866c233b43e03fc5fd4a97d585",["Text"]="-----------------------------------\n-- ID: 4197\n-- rusty_bolt_case\n-- When used, you will obtain one partial stack of Rusty Bolts\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.RUSTY_BOLT, math.randomInt(10, 20) } })\nend\n\nreturn itemObject\n"},["scripts/items/ruszor_quiver.lua"]={["Path"]="scripts/items/ruszor_quiver.lua",["SHA256"]="1a1a10ee75ee69bbf9fad573110ecfde84be993046dfed74eedf56832490892a",["Text"]="-----------------------------------\n-- ID: 5871\n-- Ruszor Quiver\n-- When used, you will obtain one stack of Ruszor Arrows\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.RUSZOR_ARROW, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/sacred_degen.lua"]={["Path"]="scripts/items/sacred_degen.lua",["SHA256"]="3e623c38e60b8ce6853fba0ae00bb4c49ab9697443f7da7fdb6e3987f3f01708",["Text"]="-----------------------------------\n-- ID: 17683\n-- Item: Sacred Degen\n-- Additional effect: light damage\n-- Enchantment: Enlight\n-- Duration: 3 minutes\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat = actor:getStat(xi.mod.MND) - target:getStat(xi.mod.INT)\n    local pTable =\n    {\n        chance         = utils.clamp(dStat * 4 / 9, 0, 24), -- Seems to be a linear scale over 54 dSTAT, 4 / 9 = 0.4444...\n        basePower      = math.randomInt(4, 6),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.LIGHT,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nitemObject.onItemCheck = function(target, user)\n    if target:getStatusEffectBySource(xi.effect.ENLIGHT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.SACRED_DEGEN) ~= nil then\n        target:delStatusEffect(xi.effect.ENLIGHT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.SACRED_DEGEN)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.SACRED_DEGEN) then\n        target:addStatusEffect(xi.effect.ENLIGHT, { duration = 180, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.SACRED_DEGEN })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    local magicskill = target:getSkillLevel(xi.skill.ENHANCING_MAGIC)\n    local potency    = 0\n\n    if magicskill <= 200 then\n        potency = 3 + math.floor(6 * magicskill / 100)\n    elseif magicskill > 200 then\n        potency = 5 + math.floor(5 * magicskill / 100)\n    end\n\n    potency = utils.clamp(potency, 3, 25)\n    effect:addMod(xi.mod.ENSPELL, xi.element.LIGHT)\n    effect:addMod(xi.mod.ENSPELL_DMG, potency)\n    effect:addMod(xi.mod.ENSPELL_CHANCE, 100)\nend\n\n-- Needed for onEffectGain to work\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/sacred_lance.lua"]={["Path"]="scripts/items/sacred_lance.lua",["SHA256"]="8e16f9ae9f9cbbd498629107a1b3ab030e10e2ff03d6f94027cf16d137902b6b",["Text"]="-----------------------------------\n-- ID: 16858\n-- Item: Sacred Lance\n-- Additional effect: light damage\n-- Enchantment: Enlight\n-- Duration: 3 minutes\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat = actor:getStat(xi.mod.MND) - target:getStat(xi.mod.INT)\n    local pTable =\n    {\n        chance         = utils.clamp(dStat * 4 / 9, 0, 24), -- Seems to be a linear scale over 54 dSTAT, 4 / 9 = 0.4444...\n        basePower      = math.randomInt(19, 25),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.LIGHT,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getStatusEffectBySource(xi.effect.ENLIGHT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.SACRED_LANCE) ~= nil then\n        target:delStatusEffect(xi.effect.ENLIGHT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.SACRED_LANCE)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.SACRED_LANCE) then\n        target:addStatusEffect(xi.effect.ENLIGHT, { duration = 180, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.SACRED_LANCE })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    local magicskill = target:getSkillLevel(xi.skill.ENHANCING_MAGIC)\n    local potency = 0\n\n    if magicskill <= 200 then\n        potency = 3 + math.floor(6 * magicskill / 100)\n    elseif magicskill > 200 then\n        potency = 5 + math.floor(5 * magicskill / 100)\n    end\n\n    potency = utils.clamp(potency, 3, 25)\n    effect:addMod(xi.mod.ENSPELL, xi.element.LIGHT)\n    effect:addMod(xi.mod.ENSPELL_DMG, potency)\n    effect:addMod(xi.mod.ENSPELL_CHANCE, 100)\nend\n\n-- Needed for onEffectGain to work\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/sacred_mace.lua"]={["Path"]="scripts/items/sacred_mace.lua",["SHA256"]="f97937bbc156069fd8c7fd040bd0ab3e02f4d3995c20f65e8f84a94362dd8faf",["Text"]="-----------------------------------\n-- ID: 18391\n-- Item: Sacred Mace\n-- Additional effect: light damage\n-- Enchantment: Enlight\n-- Duration: 3 minutes\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat = actor:getStat(xi.mod.MND) - target:getStat(xi.mod.INT)\n    local pTable =\n    {\n        chance         = utils.clamp(dStat * 4 / 9, 0, 24), -- Seems to be a linear scale over 54 dSTAT, 4 / 9 = 0.4444...\n        basePower      = math.randomInt(7, 9),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.LIGHT,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nitemObject.onItemCheck = function(target, user)\n    if target:getStatusEffectBySource(xi.effect.ENLIGHT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.SACRED_MACE) ~= nil then\n        target:delStatu