, 24), -- Seems to be a linear scale over 54 dSTAT, 4 / 9 = 0.4444...\n        basePower      = math.randomInt(5, 7),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.LIGHT,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nitemObject.onItemCheck = function(target, user)\n    if target:getStatusEffectBySource(xi.effect.ENLIGHT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.SACRED_SWORD) ~= nil then\n        target:delStatusEffect(xi.effect.ENLIGHT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.SACRED_SWORD)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.SACRED_SWORD) then\n        target:addStatusEffect(xi.effect.ENLIGHT, { duration = 180, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.SACRED_SWORD })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    local magicskill = target:getSkillLevel(xi.skill.ENHANCING_MAGIC)\n    local potency = 0\n\n    if magicskill <= 200 then\n        potency = 3 + math.floor(6 * magicskill / 100)\n    elseif magicskill > 200 then\n        potency = 5 + math.floor(5 * magicskill / 100)\n    end\n\n    potency = utils.clamp(potency, 3, 25)\n    effect:addMod(xi.mod.ENSPELL, xi.element.LIGHT)\n    effect:addMod(xi.mod.ENSPELL_DMG, potency)\n    effect:addMod(xi.mod.ENSPELL_CHANCE, 100)\nend\n\n-- Needed for onEffectGain to work\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/sacred_wand.lua"]={["Path"]="scripts/items/sacred_wand.lua",["SHA256"]="014c874e098db5e49faff45f39e47fd0281e78c1531ab101e28fdf4e88b80712",["Text"]="-----------------------------------\n-- ID: 18393\n-- Item: Sacred Wand\n-- Additional effect: light damage\n-- Enchantment: Enlight\n-- Duration: 3 minutes\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat = actor:getStat(xi.mod.MND) - target:getStat(xi.mod.INT)\n    local pTable =\n    {\n        chance         = utils.clamp(dStat * 4 / 9, 0, 24), -- Seems to be a linear scale over 54 dSTAT, 4 / 9 = 0.4444...\n        basePower      = math.randomInt(7, 9),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.LIGHT,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nitemObject.onItemCheck = function(target, user)\n    if target:getStatusEffectBySource(xi.effect.ENLIGHT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.SACRED_WAND) ~= nil then\n        target:delStatusEffect(xi.effect.ENLIGHT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.SACRED_WAND)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.SACRED_WAND) then\n        target:addStatusEffect(xi.effect.ENLIGHT, { duration = 180, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.SACRED_WAND })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    local magicskill = target:getSkillLevel(xi.skill.ENHANCING_MAGIC)\n    local potency = 0\n\n    if magicskill <= 200 then\n        potency = 3 + math.floor(6 * magicskill / 100)\n    elseif magicskill > 200 then\n        potency = 5 + math.floor(5 * magicskill / 100)\n    end\n\n    potency = utils.clamp(potency, 3, 25)\n    effect:addMod(xi.mod.ENSPELL, xi.element.LIGHT)\n    effect:addMod(xi.mod.ENSPELL_DMG, potency)\n    effect:addMod(xi.mod.ENSPELL_CHANCE, 100)\nend\n\n-- Needed for onEffectGain to work\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/sacrifice_torque.lua"]={["Path"]="scripts/items/sacrifice_torque.lua",["SHA256"]="a78d279aaca6e3d7d6395459fbd88f90a154f3738c41e95fd7d8e7cabedc4f84",["Text"]="-----------------------------------\n-- ID: 15528\n-- Sacrifice Torque\n-- Pet mod via latent effect\n-- Latents are added to player before OnItemEquip is called\n-- Latents are removed from player before OnItemUnequip is called\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\nlocal listenerPrefix = 'PET_MOD_LATENT'\nlocal latentPetId = nil\nlocal latentMods =\n{\n    { xi.mod.ATT, 3 },\n}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemEquip  = function(user, item)\n    local listenerName = fmt('{}_{}', listenerPrefix, item:getID())\n    if user:hasAllLatentsActive(xi.slot.NECK) then\n        user:setLocalVar(listenerName, 1)\n        xi.itemUtils.handlePetLatentMods(user, latentPetId, latentMods, true)\n    end\n\n    user:addListener('MAGIC_STATE_EXIT', listenerName, function(player, spell)\n        if spell:getSpellGroup() == xi.magic.spellGroup.SUMMONING then\n            player:setLocalVar(listenerName, 1)\n            xi.itemUtils.handlePetLatentMods(user, latentPetId, latentMods, true)\n        end\n    end)\nend\n\nitemObject.onItemUnequip = function(user, item)\n    local listenerName = fmt('{}_{}', listenerPrefix, item:getID())\n    if user:getLocalVar(listenerName) == 1 then\n        xi.itemUtils.handlePetLatentMods(user, latentPetId, latentMods, false)\n    end\n\n    user:setLocalVar(listenerName, 0)\n    user:removeListener(listenerName)\nend\n\nreturn itemObject\n"},["scripts/items/safehold_earring.lua"]={["Path"]="scripts/items/safehold_earring.lua",["SHA256"]="4ae0e8019c7a0f7116701dd4a9fa1ef79fdb81e7f95483430e87cd93acead2fd",["Text"]="-----------------------------------\n-- ID: 16048\n-- Safehold Earring\n-- Enchantment: \"Teleport\" (Tavnazian Safehold)\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.SAFEHOLD_EARRING, duration = 4, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/sakura_biscuit.lua"]={["Path"]="scripts/items/sakura_biscuit.lua",["SHA256"]="c8790af1a5169f97dae3651df553f49a2aa3b59549f6c5ad625aac1456c04e57",["Text"]="-----------------------------------\n-- ID: 6010\n-- Item: Sakura Biscuit\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Intelligence 3\n-- Charisma 2\n-- Evasion +2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.INT, 3)\n    effect:addMod(xi.mod.CHR, 2)\n    effect:addMod(xi.mod.EVA, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/salmon_croute.lua"]={["Path"]="scripts/items/salmon_croute.lua",["SHA256"]="f935d30288634537de7e894d13b6c74281dd03d16b14be43b312ffad7040095a",["Text"]="-----------------------------------\n-- ID: 4551\n-- Item: salmon_croute\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- MP +3% (cap 130)\n-- Dexterity 2\n-- MND -2\n-- Ranged Accuracy +6% (cap 15)\n-- HP recovered while healing 2\n-- MP recovered while healing 1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MPP, 3)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 130)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.MND, -2)\n    effect:addMod(xi.mod.FOOD_RACCP, 6)\n    effect:addMod(xi.mod.FOOD_RACC_CAP, 15)\n    effect:addMod(xi.mod.HPHEAL, 2)\n    effect:addMod(xi.mod.MPHEAL, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/salmon_rice_ball.lua"]={["Path"]="scripts/items/salmon_rice_ball.lua",["SHA256"]="f59015c68946f0fac513a33529811bf5c980ec50caf3f7ef9f4504522a4d63c8",["Text"]="-----------------------------------\n-- ID: 4590\n-- Item: Salmon Rice Ball\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- HP +10\n-- Dex +2\n-- Vit +2\n-- Mnd -1\n-- hHP +1\n-- Effect with enhancing equipment (Note: these are latents on gear with the effect)\n-- Atk +40\n-- Def +40\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 10)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.VIT, 2)\n    effect:addMod(xi.mod.MND, -1)\n    effect:addMod(xi.mod.HPHEAL, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/salmon_sub_sandwich.lua"]={["Path"]="scripts/items/salmon_sub_sandwich.lua",["SHA256"]="a78cce2a7e6d09953bdf7ff6f4d972303d6b832fa782245f16d87115887c5fc9",["Text"]="-----------------------------------\n-- ID: 4355\n-- Item: salmon_sub_sandwich\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Dexterity 2\n-- Agility 1\n-- Vitality 1\n-- Intelligence 2\n-- Mind -2\n-- Ranged ACC 2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.AGI, 1)\n    effect:addMod(xi.mod.VIT, 1)\n    effect:addMod(xi.mod.INT, 2)\n    effect:addMod(xi.mod.MND, -2)\n    effect:addMod(xi.mod.RACC, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/saltena.lua"]={["Path"]="scripts/items/saltena.lua",["SHA256"]="76b9c7b92cb6def4f08c639b41cd8a58bef8b1742577377b1354da3e7bfa471c",["Text"]="-----------------------------------\n-- ID: 5885\n-- Item: saltena\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- HP +6% (cap 100)\n-- Increases rate of combat skill gains by 20%\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HPP, 6)\n    effect:addMod(xi.mod.FOOD_HP_CAP, 100)\n    effect:addMod(xi.mod.COMBAT_SKILLUP_RATE, 20)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/salty_bretzel.lua"]={["Path"]="scripts/items/salty_bretzel.lua",["SHA256"]="f6b254bdd02858e2b59f5364c8b0eb19a37adc57cf4dc6987472e2563323907e",["Text"]="-----------------------------------\n-- ID: 5182\n-- Item: salty_bretzel\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Magic % 8\n-- Magic Cap 60\n-- Vitality 2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MPP, 8)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 60)\n    effect:addMod(xi.mod.VIT, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/samsonian_belt.lua"]={["Path"]="scripts/items/samsonian_belt.lua",["SHA256"]="da9f966fe224fa6eb29266530f1dc6afe639acef93a3d79c58f2650e28d5cc51",["Text"]="-----------------------------------\n-- ID: 15863\n-- Item: samsonian_belt\n-- Item Effect: STR +3\n-- Duration: 60 seconds\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getStatusEffectBySource(xi.effect.STR_BOOST, xi.effectSourceType.EQUIPPED_ITEM, xi.item.SAMSONIAN_BELT) ~= nil then\n        target:delStatusEffect(xi.effect.STR_BOOST, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.SAMSONIAN_BELT)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.SAMSONIAN_BELT) then\n        target:addStatusEffect(xi.effect.STR_BOOST, { power = 3, duration = 60, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.SAMSONIAN_BELT })\n    end\nend\n\nreturn itemObject\n"},["scripts/items/samurai_die.lua"]={["Path"]="scripts/items/samurai_die.lua",["SHA256"]="6824ac3a1351281dffcade08198771f708beffbc72247890444371b04455441e",["Text"]="-----------------------------------\n-- ID: 5488\n-- Samurai Die\n-- Teaches the job ability Samurai Roll\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnAbility(xi.jobAbility.SAMURAI_ROLL)\nend\n\nitemObject.onItemUse = function(target)\n    target:addLearnedAbility(xi.jobAbility.SAMURAI_ROLL)\nend\n\nreturn itemObject\n"},["scripts/items/san_dorian_carrot.lua"]={["Path"]="scripts/items/san_dorian_carrot.lua",["SHA256"]="cc4ff9c6e21c31fad3d1cf79ddc8beceb1618758f2e8b380a6f917c123ee2010",["Text"]="-----------------------------------\n-- ID: 4389\n-- Item: san_dorian_carrot\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Agility 2\n-- Vitality -4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, 2)\n    effect:addMod(xi.mod.VIT, -4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/sanation_ring.lua"]={["Path"]="scripts/items/sanation_ring.lua",["SHA256"]="b859087e6b0c07518e2df824b18ee9954db94ece71577f8217b4c12117b23ea4",["Text"]="-----------------------------------\n-- ID: 14677\n-- Item: Sanation Ring\n-- Item Effect: MP recovered while healing +3\n-- Duration: 3 Minutes\n-- https://wiki.ffo.jp/html/2190.html\n-- TODO: Capture Icon\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.SANATION_RING) then\n        local effect = target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.SANATION_RING)\n        if effect then\n            effect:resetStartTime()\n        else\n            target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 180, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.SANATION_RING })\n        end\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.MPHEAL, 3)\nend\n\nitemObject.onItemUnequip = function(target, item)\n    target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.SANATION_RING)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/sandfish.lua"]={["Path"]="scripts/items/sandfish.lua",["SHA256"]="962eea9951cc581c5602f0a55a93e9fe351f4b8084d97ebf43f549d013f8b117",["Text"]="-----------------------------------\n-- ID: 4291\n-- Item: sandfish\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 3\n-- Mind -5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 3)\n    effect:addMod(xi.mod.MND, -5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/sandstorm_schema.lua"]={["Path"]="scripts/items/sandstorm_schema.lua",["SHA256"]="88e5f2faac5eeb1e840574827e1df0b02d99027a562a6a6ea8dfe491bafeac0c",["Text"]="-----------------------------------\n-- ID: 6053\n-- Sandstorm Schema\n-- Teaches the white magic Sandstorm\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnSpell(xi.magic.spell.SANDSTORM)\nend\n\nitemObject.onItemUse = function(target)\n    target:addSpell(xi.magic.spell.SANDSTORM)\nend\n\nreturn itemObject\n"},["scripts/items/saruta_orange.lua"]={["Path"]="scripts/items/saruta_orange.lua",["SHA256"]="129fd13828884e6027993a84bf119c8ff79d851b0e73ad42e63aee8fe3d54f32",["Text"]="-----------------------------------\n-- ID: 4392\n-- Item: saruta_orange\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Agility -3\n-- Intelligence 1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, -3)\n    effect:addMod(xi.mod.INT, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/sasuke_shuriken_pouch.lua"]={["Path"]="scripts/items/sasuke_shuriken_pouch.lua",["SHA256"]="48716ce1803667ace76802b68d34239bab023947bbb18eef25fcb37e5f2ba146",["Text"]="-----------------------------------\n-- ID: 6447\n-- Sasu. Sh. Pouch\n-- A small leather pouch made for storing sasuke shuriken.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.SASUKE_SHURIKEN, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/sasuke_shuriken_pouch_+1.lua"]={["Path"]="scripts/items/sasuke_shuriken_pouch_+1.lua",["SHA256"]="bbb3e02a09cb2be7d1c18213d3665435c2a050d5719b412fb339b8513a35a067",["Text"]="-----------------------------------\n-- ID: 6448\n-- Sasu. Sh. Pouch +1\n-- A small leather pouch made for storing sasuke shuriken +1.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.SASUKE_SHURIKEN_P1, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/sattva_ring.lua"]={["Path"]="scripts/items/sattva_ring.lua",["SHA256"]="ba3d3d47e603316e86691fcaf2c19eb5435d949cb4fae276cb1b1a08b4871b7c",["Text"]="-----------------------------------\n-- ID: 15544\n-- Sattva Ring\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\nend\n\nitemObject.onItemUse = function(target)\nend\n\nitemObject.onItemDrop = function(target, item, recycleBin)\n    if not recycleBin then\n        xi.mission.setVar(target, xi.mission.log_id.COP, xi.mission.id.cop.DAWN, 'Timer', 1, GetSystemTime() + 27 * 24 * 60 * 60)\n    end\nend\n\nreturn itemObject\n"},["scripts/items/sausage.lua"]={["Path"]="scripts/items/sausage.lua",["SHA256"]="a3f4b0781257c9cbded40145806428d5baf71a1deb44b90efe8ffdc4bd3716b5",["Text"]="-----------------------------------\n-- ID: 4578\n-- Item: sausage\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Health % 3 (cap 130)\n-- Strength 3\n-- Intelligence -1\n-- Attack % 27\n-- Attack Cap 30\n-- Ranged ATT % 27\n-- Ranged ATT Cap 30\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HPP, 3)\n    effect:addMod(xi.mod.FOOD_HP_CAP, 130)\n    effect:addMod(xi.mod.STR, 3)\n    effect:addMod(xi.mod.INT, -1)\n    effect:addMod(xi.mod.FOOD_ATTP, 27)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 30)\n    effect:addMod(xi.mod.FOOD_RATTP, 27)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 30)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/sausage_roll.lua"]={["Path"]="scripts/items/sausage_roll.lua",["SHA256"]="7a3ac3697e9c5ae83232938a3d75ed61d8f7926d1d9814255ac9960a751317c6",["Text"]="-----------------------------------\n-- ID: 4396\n-- Item: sausage_roll\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Health % 6 (cap 160)\n-- Vitality 3\n-- Intelligence -1\n-- Attack % 27\n-- Attack Cap 30\n-- Ranged ATT % 27\n-- Ranged ATT Cap 30\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HPP, 6)\n    effect:addMod(xi.mod.FOOD_HP_CAP, 160)\n    effect:addMod(xi.mod.VIT, 3)\n    effect:addMod(xi.mod.INT, -1)\n    effect:addMod(xi.mod.FOOD_ATTP, 27)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 30)\n    effect:addMod(xi.mod.FOOD_RATTP, 27)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 30)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/savage_top_+1.lua"]={["Path"]="scripts/items/savage_top_+1.lua",["SHA256"]="9f07875265ce2031dc9209fedd5bf5441d3e8721ca25583fb6a61e8c79f5b6ae",["Text"]="-----------------------------------\n-- ID: 11279\n-- Item: savage top +1\n-- Teleport's user to Purgonorgo Isle\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    if not target:hasVisitedZone(xi.zone.BIBIKI_BAY) then\n        result = xi.msg.basic.ITEM_UNABLE_TO_USE_2\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.PURGONORGO, duration = 3, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/sazanbaligi.lua"]={["Path"]="scripts/items/sazanbaligi.lua",["SHA256"]="94037ea28e8bed5765e54a1adeeebdf48f2d3fcd1020d2c6d69107c1383ff163",["Text"]="-----------------------------------\n-- ID: 5459\n-- Item: Sazanbaligi\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 4\n-- Mind -6\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 4)\n    effect:addMod(xi.mod.MND, -6)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/scapegoat.lua"]={["Path"]="scripts/items/scapegoat.lua",["SHA256"]="3f4072083a4596f94fd6929e9240089c91dc0bfec23f856036ba2a257a85b1a1",["Text"]="-----------------------------------\n-- ID: 5412\n-- scapegoat\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    local power = 1\n    local duration = 1800\n\n    if target:hasStatusEffect(xi.effect.RERAISE) then\n        local effect = target:getStatusEffect(xi.effect.RERAISE)\n        if not effect then\n            return\n        end\n\n        local oPower = effect:getPower()\n\n        if oPower > power then\n            target:messageBasic(xi.msg.basic.NO_EFFECT)\n        else\n            target:delStatusEffect(xi.effect.RERAISE)\n            target:addStatusEffect(xi.effect.RERAISE, { power = power, duration = duration, origin = user })\n        end\n    else\n        target:addStatusEffect(xi.effect.RERAISE, { power = power, duration = duration, origin = user })\n    end\nend\n\nreturn itemObject\n"},["scripts/items/scholar_die.lua"]={["Path"]="scripts/items/scholar_die.lua",["SHA256"]="ac6c8510c2efcc4f40d9ed8d90207949c1d9de9444f80603efeee284bfe33dc4",["Text"]="-----------------------------------\n-- ID: 5496\n-- Scholar Die\n-- Teaches the job ability Scholars Roll\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnAbility(xi.jobAbility.SCHOLARS_ROLL)\nend\n\nitemObject.onItemUse = function(target)\n    target:addLearnedAbility(xi.jobAbility.SCHOLARS_ROLL)\nend\n\nreturn itemObject\n"},["scripts/items/scorpion_quiver.lua"]={["Path"]="scripts/items/scorpion_quiver.lua",["SHA256"]="57a9d82dfc3377a64b5d95f18652298ce9a26e086f1afcd72b8e45068061bf26",["Text"]="-----------------------------------\n-- ID: 4223\n-- Scorpion Quiver\n-- When used, you will obtain one stack of Scorpion Arrows\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.SCORPION_ARROW, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/scouts_bolt.lua"]={["Path"]="scripts/items/scouts_bolt.lua",["SHA256"]="142cb95d528e65ec8989ca5fa98806132052b53d829b8bf01ab3f0e30c6c3d2b",["Text"]="-----------------------------------\n-- ID: 22287\n-- Item: Scouts Bolt\n-- Additional effect: Light damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat = actor:getStat(xi.mod.MND) - target:getStat(xi.mod.MND)\n    -- Unconfirmed power.\n\n    local pTable =\n    {\n        ignoreEnSpell   = true,\n        basePower       = 40 + utils.clamp(dStat, -3, 8) + utils.clamp(math.floor((dStat - 8) / 2), 0, 8),\n        attackType      = xi.attackType.MAGICAL,\n        magicalElement  = xi.element.LIGHT,\n        canResist       = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/scream_fungus.lua"]={["Path"]="scripts/items/scream_fungus.lua",["SHA256"]="783cf8ae35cc78b1a61fefb3e70a483064dc61b8ccad0d6009844b26ae1b6744",["Text"]="-----------------------------------\n-- ID: 4447\n-- Item: scream_fungus\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Strength -4\n-- Mind 2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.STR, -4)\n    effect:addMod(xi.mod.MND, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/scroll_of_absorb-acc.lua"]={["Path"]="scripts/items/scroll_of_absorb-acc.lua",["SHA256"]="a548b499d3ac866f64ba73ed7698b5c925195fcb326e5263b19f13390fd42514",["Text"]="-----------------------------------\n-- ID: 4886\n-- Scroll of Absorb-ACC\n-- Teaches the black magic Absorb-ACC\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnSpell(xi.magic.spell.ABSORB_ACC)\nend\n\nitemObject.onItemUse = function(target)\n    target:addSpell(xi.magic.spell.ABSORB_ACC)\nend\n\nreturn itemObject\n"},["scripts/items/scroll_of_absorb-agi.lua"]={["Path"]="scripts/items/scroll_of_absorb-agi.lua",["SHA256"]="e81da5d782f5438f16e79d495ac690127b5e5df87946c67606ea2d2dd4f5bb82",["Text"]="-----------------------------------\n-- ID: 4877\n-- Scroll of Absorb-AGI\n-- Teaches the black magic Absorb-AGI\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnSpell(xi.magic.spell.ABSORB_AGI)\nend\n\nitemObject.onItemUse = function(target)\n    target:addSpell(xi.magic.spell.ABSORB_AGI)\nend\n\nreturn itemObject\n"},["scripts/items/scroll_of_absorb-attri.lua"]={["Path"]="scripts/items/scroll_of_absorb-attri.lua",["SHA256"]="b3c08fca0091fe0762c81811879d452e0ab7a980b110a8b45254281479ef5b4d",["Text"]="----------------------------